import type { ThemeFamilyId, ThemeMode } from "../../theme/colors";

export type IconStyleId = "pixel" | "shikashi";

// Each style needs its lookup maps registered in iconAssets.ts and a label
// here. Shikashi maps are generated by scripts/build_shikashi_icons.py.
export const ICON_STYLES: Record<IconStyleId, { label: string; description: string }> = {
  pixel: { label: "Raven Fantasy Icons", description: "Colorful pixel art (default)." },
  shikashi: {
    label: "Shikashi's Fantasy Icons",
    description: "Drop-shadow version. Best on light and lighter themes.",
  },
};

export const ICON_STYLE_ORDER: IconStyleId[] = ["pixel", "shikashi"];

export const DEFAULT_ICON_STYLE: IconStyleId = "pixel";

/** What the user picked: a specific style, or "auto" to follow the active theme. */
export type IconStylePreference = IconStyleId | "auto";

export const DEFAULT_ICON_STYLE_PREFERENCE: IconStylePreference = "auto";

export const AUTO_ICON_STYLE_OPTION = {
  label: "Auto (follow theme)",
  description: "Picks the icon set that suits the current theme and light/dark mode.",
};

// Families whose look suits one set regardless of mode. Everything else
// falls back to the drop-shadow set on light modes and Raven on dark modes.
const FAMILY_ICON_STYLE: Partial<Record<ThemeFamilyId, IconStyleId>> = {
  classic: "pixel", // Forest
  crimson: "pixel",
};

export function resolveIconStyle(
  preference: IconStylePreference,
  family: ThemeFamilyId,
  mode: ThemeMode
): IconStyleId {
  if (preference !== "auto") return preference;
  return FAMILY_ICON_STYLE[family] ?? (mode === "dark" ? "pixel" : "shikashi");
}
